import React, { useState, useEffect, useRef } from 'react';
import { motion } from 'framer-motion';
import '../css/Header.css';

export default function Header() {
  const [activeSection, setActiveSection] = useState('home');
  const [isScrolling, setIsScrolling] = useState(false);
  const scrollTimeout = useRef(null);

  // Scroll detection for mobile labels
  useEffect(() => {
    const handleScroll = () => {
      setIsScrolling(true);
      if (scrollTimeout.current) {
        clearTimeout(scrollTimeout.current);
      }
      scrollTimeout.current = setTimeout(() => {
        setIsScrolling(false);
      }, 1500); // Labels stay visible for 1.5s after scroll stops
    };

    window.addEventListener('scroll', handleScroll, { passive: true });
    return () => {
      window.removeEventListener('scroll', handleScroll);
      if (scrollTimeout.current) clearTimeout(scrollTimeout.current);
    };
  }, []);

  // Intersection Observer to detect which section is currently on screen
  useEffect(() => {
    const observer = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          setActiveSection(entry.target.id);
        }
      });
    }, { 
      // Trigger when section is roughly halfway in view
      rootMargin: "-40% 0px -40% 0px"
    });

    // We assume sections have standard IDs matching our navLinks
    const sections = document.querySelectorAll('section[id]');
    sections.forEach(section => observer.observe(section));

    return () => {
      sections.forEach(section => observer.unobserve(section));
    };
  }, []);

  const navLinks = [
    { name: 'HOME', href: '#home', id: 'home' },
    { name: 'ABOUT', href: '#about', id: 'about' },
    { name: 'SKILLS', href: '#skills', id: 'skills' },
    { name: 'PROJECTS', href: '#projects', id: 'projects' },
    { name: 'CONTACT', href: '#contact', id: 'contact' },
  ];

  return (
    <>
      {/* Top Left Logo (since we replaced the top navbar) */}
      <motion.a 
        href="#home" 
        draggable={false} 
        initial={{ opacity: 0, x: -20 }}
        animate={{ opacity: 1, x: 0 }}
        transition={{ duration: 0.8, delay: 0.5 }}
        style={{ 
          position: 'fixed',
          top: '30px',
          left: '30px',
          zIndex: 9999,
          textDecoration: 'none', 
          fontSize: '1.5rem', 
          fontWeight: 800, 
          letterSpacing: '-0.02em',
          color: '#FFF',
          display: 'flex',
          alignItems: 'center',
          gap: '0.5rem'
        }}
      >
        Dhruv<span style={{ color: '#F08C3A' }}>.</span>
      </motion.a>

      {/* Right Middle Dot Navigation */}
      <motion.nav 
        className={`vertical-nav ${isScrolling ? 'is-scrolling' : ''}`}
        initial={{ opacity: 0, x: 50, y: "-50%" }}
        animate={{ opacity: 1, x: 0, y: "-50%" }}
        transition={{ duration: 0.8, delay: 0.8, ease: "easeOut" }}
      >
        {navLinks.map((link) => {
          const isActive = activeSection === link.id;
          return (
            <a 
              key={link.name} 
              href={link.href}
              className={`nav-dot-container ${isActive ? 'active' : ''}`}
              draggable={false}
              onClick={(e) => {
                // Let the browser scroll to the href hash natively
                setActiveSection(link.id);
              }}
            >
              <span className="nav-text">{link.name}</span>
              <div className="nav-dot"></div>
            </a>
          );
        })}
      </motion.nav>
    </>
  );
}
