import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';

export const ShimmerSkeleton = ({ className = "", style = {} }) => {
  return (
    <div className={`relative overflow-hidden bg-zinc-900/50 rounded-lg ${className}`} style={{ backgroundColor: 'rgba(24, 24, 27, 0.5)', position: 'relative', overflow: 'hidden', borderRadius: '0.5rem', ...style }}>
      <motion.div
        initial={{ x: "-100%" }}
        animate={{ x: "100%" }}
        transition={{ repeat: Infinity, duration: 1.5, ease: "linear" }}
        style={{
          position: 'absolute', inset: 0,
          background: 'linear-gradient(to right, transparent, rgba(255,255,255,0.03), transparent)',
          transform: 'skewX(-20deg)'
        }}
      />
    </div>
  );
};



export default function SystemBootLoader({ children }) {
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const timer = setTimeout(() => setLoading(false), 2500);
    return () => clearTimeout(timer);
  }, []);

  return (
    <>
      <AnimatePresence mode="wait">
        {loading ? (
          <motion.div 
            key="loader"
            exit={{ opacity: 0, scale: 1.1, filter: "blur(20px)" }}
            style={{ position: 'fixed', inset: 0, zIndex: 200, backgroundColor: '#000', display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', padding: '2.5rem' }}
          >
            <div style={{ width: '100%', maxWidth: '28rem', display: 'flex', flexDirection: 'column', gap: '2rem' }}>
              <div style={{ display: 'flex', flexDirection: 'column', gap: '1rem' }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', fontFamily: 'monospace', fontSize: '10px', color: '#71717a', textTransform: 'uppercase', letterSpacing: '0.3em' }}>
                  <span>Initializing_Core</span>
                  <span>78%</span>
                </div>
                <ShimmerSkeleton style={{ height: '0.25rem', width: '100%' }} />
              </div>
              
              <div style={{ display: 'grid', gridTemplateColumns: 'repeat(2, minmax(0, 1fr))', gap: '1rem' }}>
                <ShimmerSkeleton style={{ height: '8rem' }} />
                <ShimmerSkeleton style={{ height: '8rem' }} />
              </div>

              <div style={{ textAlign: 'center' }}>
                <p style={{ fontSize: '10px', fontFamily: 'monospace', color: '#3f3f46', animation: 'pulse 2s cubic-bezier(0.4, 0, 0.6, 1) infinite', textTransform: 'uppercase', letterSpacing: '0.1em' }}>
                  Establishing Neural Link...
                </p>
              </div>
            </div>
          </motion.div>
        ) : (
          <motion.div 
            key="content"
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.8, ease: "circOut" }}
          >
            {children}
          </motion.div>
        )}
      </AnimatePresence>
    </>
  );
}
