import React, { useEffect, useRef } from 'react';

export default function AuroraBackground() {
  const mountRef = useRef(null);

  useEffect(() => {
    // Dynamically load the WebGL fluid simulation script
    const script = document.createElement('script');
    script.src = process.env.PUBLIC_URL + '/fluid.js';
    script.async = true;
    document.body.appendChild(script);

    return () => {
      // Clean up the script tag when the component unmounts
      if (document.body.contains(script)) {
        document.body.removeChild(script);
      }
      // Note: The fluid.js script registers global event listeners (mousemove, resize, etc.)
      // and runs a requestAnimationFrame loop. Since it's meant to be a global background,
      // it doesn't have a built-in cleanup function, so it will continue running.
    };
  }, []);

  return (
    <div 
      ref={mountRef} 
      style={{ position: 'fixed', inset: 0, zIndex: 0, pointerEvents: 'none', backgroundColor: '#000000' }}
    >
      <canvas 
        id="fluid-canvas" 
        style={{ width: '100vw', height: '100vh' }}
      ></canvas>
    </div>
  );
}
