import React, { createContext, useContext, useState } from 'react';

const CursorContext = createContext(undefined);

export const CursorProvider = ({ children }) => {
  const [type, setType] = useState('default');
  const [label, setLabel] = useState('');

  return (
    <CursorContext.Provider value={{ type, setType, label, setLabel }}>
      {children}
    </CursorContext.Provider>
  );
};

export const useCursor = () => {
  const context = useContext(CursorContext);
  if (!context) throw new Error("useCursor must be used within CursorProvider");
  return context;
};

export const CursorTrigger = ({ children, type, label = "", className = "", style = {} }) => {
  const { setType, setLabel } = useCursor();
  return (
    <div 
      onMouseEnter={() => { setType(type); setLabel(label); }}
      onMouseLeave={() => { setType('default'); setLabel(''); }}
      className={className}
      style={{ display: 'inline-block', width: '100%', height: '100%', ...style }}
    >
      {children}
    </div>
  );
};
