import React, { useEffect, useState } from 'react';
import { motion, useMotionValue, useSpring, AnimatePresence } from 'framer-motion';
import { useCursor } from '../context/CursorContext';

export default function CustomCursor() {
  const { type, label } = useCursor();
  const [fallbackHover, setFallbackHover] = useState(false);
  
  const mouseX = useMotionValue(-100);
  const mouseY = useMotionValue(-100);

  // Snappier, less laggy spring settings
  const springConfig = { damping: 35, stiffness: 700, mass: 0.1 };
  const smoothX = useSpring(mouseX, springConfig);
  const smoothY = useSpring(mouseY, springConfig);

  useEffect(() => {
    const moveMouse = (e) => {
      mouseX.set(e.clientX);
      mouseY.set(e.clientY);
    };
    
    // Fallback logic for basic a/button tags that aren't wrapped in CursorTrigger
    const handleMouseOver = (e) => {
      if (e.target.closest('a, button, .magnetic, .social-icon')) {
        setFallbackHover(true);
      } else {
        setFallbackHover(false);
      }
    };

    window.addEventListener('mousemove', moveMouse, { passive: true });
    window.addEventListener('mouseover', handleMouseOver, { passive: true });

    return () => {
      window.removeEventListener('mousemove', moveMouse);
      window.removeEventListener('mouseover', handleMouseOver);
    };
  }, [mouseX, mouseY]);

  // Determine active state: Context overrides fallback
  const activeType = type !== 'default' ? type : (fallbackHover ? 'text' : 'default');

  const variants = {
    default: { height: 16, width: 16, backgroundColor: "#fff", borderRadius: "50%" },
    text: { height: 80, width: 80, backgroundColor: "#fff", borderRadius: "50%" },
    project: { height: 120, width: 120, backgroundColor: "#fff", borderRadius: "50%" },
    locked: { height: 40, width: 40, backgroundColor: "#F08C3A", borderRadius: "8px" }
  };

  // Do not render custom cursor on touch devices
  if (typeof window !== 'undefined' && window.matchMedia('(hover: none) and (pointer: coarse)').matches) {
    return null;
  }

  return (
    <motion.div
      style={{
        position: 'fixed',
        top: 0,
        left: 0,
        pointerEvents: 'none',
        zIndex: 9999,
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        mixBlendMode: 'difference',
        overflow: 'hidden',
        x: smoothX,
        y: smoothY,
        translateX: "-50%",
        translateY: "-50%"
      }}
      animate={activeType}
      variants={variants}
      initial="default"
      transition={{ type: "spring", stiffness: 300, damping: 30 }}
    >
      <AnimatePresence>
        {activeType === 'project' && (
          <motion.span
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -10 }}
            style={{ color: '#000', fontSize: '14px', fontWeight: 'bold', textTransform: 'uppercase' }}
          >
            {label || "View"}
          </motion.span>
        )}
      </AnimatePresence>
    </motion.div>
  );
}
